svg.script:
//
    (function() {
      'use strict';

      // Dados determinísticos das camadas anatômicas
      var STEPS = [
        {
          id: 'pele',
          name: 'PELE / TEGUMENTO PERINEAL',
          depth: '0 mm (Superfície)',
          y: 400,
          color: 'var(--a12p17-pele)',
          location: 'Ponto zero de entrada do exame clínico. Situado exteriormente à membrana perineal.',
          structures: [
            '• Epiderme e derme perineal',
            '• Tecido adiposo subcutâneo',
            '• Orifícios vulvares e anais externos'
          ]
        },
        {
          id: 'superficial',
          name: 'ESPAÇO PERINEAL SUPERFICIAL',
          depth: '15 mm (Superficial)',
          y: 320,
          color: 'var(--a12p17-superficial)',
          location: 'Compreendido entre a Pele e a face inferior da Membrana Perineal (andar de fora).',
          structures: [
            '• M. Bulboesponjoso & Isquiocavernoso',
            '• M. Transverso Superficial do Períneo',
            '• Corpos eréteis (Bulbos do vestíbulo e Clitóris)',
            '• Glândulas vestibulares maiores (Bartholin)'
          ]
        },
        {
          id: 'membrana',
          name: 'MEMBRANA PERINEAL (LÂMINA DIVISORA)',
          depth: '30 mm (Divisor Central)',
          y: 247,
          color: 'var(--a12p17-membrana)',
          location: 'Fáscia fibromuscular triangular espessa. Divisor anatômico entre o andar superficial e o profundo.',
          structures: [
            '• Lâmina fascial fibrosa resistente',
            '• Perfurações para passagem de fibras profundas',
            '• Hiato urogenital (passagem da uretra e vagina)',
            '• Fixação ao arco púbico lateralmente'
          ]
        },
        {
          id: 'profundo',
          name: 'ESPAÇO PERINEAL PROFUNDO',
          depth: '45 mm (Profundo)',
          y: 170,
          color: 'var(--a12p17-profundo)',
          location: 'Situado ACIMA da Membrana Perineal e ABAIXO do Diafragma Pélvico (andar de dentro).',
          structures: [
            '• M. Transverso Profundo do Períneo',
            '• M. Esfíncter Uretral Externo (Urogenital)',
            '• Fibras musculares perfurantes para a membrana',
            '• Vasos e nervos pudendos internos'
          ]
        },
        {
          id: 'diafragma',
          name: 'DIAFRAGMA PÉLVICO (M. LEVATOR ANI)',
          depth: '60 mm (Polo Interno / Visceral)',
          y: 60,
          color: 'var(--a12p17-diafragma)',
          location: 'Assoalho muscular principal da cavidade pélvica. Teto do espaço perineal profundo.',
          structures: [
            '• M. Pubococcígeo e Puborretal',
            '• M. Iliococcígeo',
            '• Fáscia superior do diafragma pélvico',
            '• Transição direta para a cavidade pélvica visceral'
          ]
        }
      ];

      var currentStepIndex = 0;

      function updateUI() {
        var step = STEPS[currentStepIndex];

        // 1. Mover a Sonda de Profundidade
        var shaft = document.getElementById('a12p17-probe-shaft');
        var tip = document.getElementById('a12p17-probe-tip');
        var glow = document.getElementById('a12p17-probe-glow');

        if (shaft && tip && glow) {
          tip.setAttribute('cy', step.y);
          glow.setAttribute('cy', step.y);
          shaft.setAttribute('y2', step.y);
        }

        // 2. Atualizar Highlight das Camadas no Desenho Anatômico
        STEPS.forEach(function(s, idx) {
          var box = document.getElementById('a12p17-box-' + s.id);
          if (box) {
            if (idx === currentStepIndex) {
              box.classList.add('active');
            } else {
              box.classList.remove('active');
            }
          }

          var navBtn = document.getElementById('a12p17-nav-' + idx);
          if (navBtn) {
            if (idx === currentStepIndex) {
              navBtn.classList.add('active');
            } else {
              navBtn.classList.remove('active');
            }
          }
        });

        // 3. Atualizar Leitura no Painel Direito
        var depthDisp = document.getElementById('a12p17-depth-display');
        var statusRect = document.getElementById('a12p17-status-rect');
        var statusTxt = document.getElementById('a12p17-status-txt');
        var infoLoc = document.getElementById('a12p17-info-location');
        var structList = document.getElementById('a12p17-struct-list');

        if (depthDisp) {
          depthDisp.innerHTML = step.depth.split(' ')[0] + ' <tspan class="a12p17-depth-unit">' + step.depth.substring(step.depth.indexOf(' ')) + '</tspan>';
        }

        if (statusRect && statusTxt) {
          statusRect.setAttribute('fill', step.color);
          statusRect.setAttribute('stroke', step.color);
          statusTxt.setAttribute('fill', step.id === 'membrana' ? '#141115' : '#ffffff');
          statusTxt.textContent = step.name;
        }

        if (infoLoc) {
          infoLoc.textContent = step.location;
        }

        if (structList) {
          // Limpar e reconstruir lista de estruturas
          while (structList.firstChild) {
            structList.removeChild(structList.firstChild);
          }

          step.structures.forEach(function(itemText, i) {
            var textEl = document.createElementNS('http://www.w3.org/2000/svg', 'text');
            textEl.setAttribute('class', 'a12p17-struct-item');
            textEl.setAttribute('x', '0');
            textEl.setAttribute('y', (i * 20).toString());
            textEl.textContent = itemText;
            structList.appendChild(textEl);
          });
        }

        // 4. Anúncio ARIA para Acessibilidade
        var ariaLive = document.getElementById('a12p17-aria-live');
        if (ariaLive) {
          ariaLive.textContent = 'Sonda posicionada em: ' + step.name + ', profundidade: ' + step.depth;
        }
      }

      function setStep(idx) {
        if (idx >= 0 && idx < STEPS.length) {
          currentStepIndex = idx;
          updateUI();
        }
      }

      function setupEvents() {
        // Eventos dos botões Passo a Passo
        var btnIn = document.getElementById('a12p17-btn-in');
        var btnOut = document.getElementById('a12p17-btn-out');

        if (btnIn) {
          btnIn.addEventListener('click', function() {
            setStep(Math.min(currentStepIndex + 1, STEPS.length - 1));
          });
          btnIn.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              setStep(Math.min(currentStepIndex + 1, STEPS.length - 1));
            }
          });
        }

        if (btnOut) {
          btnOut.addEventListener('click', function() {
            setStep(Math.max(currentStepIndex - 1, 0));
          });
          btnOut.addEventListener('keydown', function(e) {
            if (e.key === 'Enter' || e.key === ' ') {
              e.preventDefault();
              setStep(Math.max(currentStepIndex - 1, 0));
            }
          });
        }

        // Eventos dos botões de navegação direta por camada (0 a 4)
        STEPS.forEach(function(s, idx) {
          var navBtn = document.getElementById('a12p17-nav-' + idx);
          if (navBtn) {
            navBtn.addEventListener('click', function() { setStep(idx); });
            navBtn.addEventListener('keydown', function(e) {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                setStep(idx);
              }
            });
          }

          var grpItem = document.getElementById('a12p17-grp-' + s.id);
          if (grpItem) {
            grpItem.addEventListener('click', function() { setStep(idx); });
            grpItem.addEventListener('keydown', function(e) {
              if (e.key === 'Enter' || e.key === ' ') {
                e.preventDefault();
                setStep(idx);
              }
            });
          }
        });

        // Teclas de Atalho de Seta Cima/Baixo no SVG
        var rootSvg = document.getElementById('a12p17-svg');
        if (rootSvg) {
          rootSvg.addEventListener('keydown', function(e) {
            if (e.key === 'ArrowUp') {
              e.preventDefault();
              setStep(Math.min(currentStepIndex + 1, STEPS.length - 1));
            } else if (e.key === 'ArrowDown') {
              e.preventDefault();
              setStep(Math.max(currentStepIndex - 1, 0));
            }
          });
        }
      }

      // Inicialização
      document.addEventListener('DOMContentLoaded', function() {
        setupEvents();
        updateUI();
      });

      // Executar imediatamente se o DOM já estiver pronto
      if (document.readyState === 'interactive' || document.readyState === 'complete') {
        setupEvents();
        updateUI();
      }
    })();
  //
